import gsap from 'gsap';

import { Device } from '@game-studio/device';

import { SharedMessageView } from './shared-message-view';

export class MessageView extends SharedMessageView {
    protected get tweenTargets(): gsap.TweenTarget[] { return [this.messageText]; }
    protected get maskWidth(): number { return this.isLeftHanded ? this.maxDimensions.width : -this.maxDimensions.width; }

    constructor(device: Device) {
        super(device);

        this.createText();

        this.name = 'message-view';
    }

    protected override createText(): void {
        super.createText();

        this.messageText.anchor.set(1, 0.5);
        this.messageText.name = 'message-view-text';
    }

    protected updateMessageScale(): void {
        const scale = this.calculateRequiredScale();

        this.applyCalculatedScale(scale);
    }

    protected calculateRequiredScale(): number {
        this.messageText.scale.set(1);
        return this.calculateTextScale(this.messageText.width, this.messageText.height);
    }

    protected applyCalculatedScale(scale: number): void {
        this.messageText.scale.set(scale);
        this.messageText.anchor.set(this.isLeftHanded ? 0 : 1, 0.5);
        this.messageText.position.set(0, this.animateOnTargetY);
    }
}